<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { listarTrabajadores, obtenerFichaTrabajador, urlFichaTrabajadorPdf } from '../services/trabajadores'
import type { FichaTrabajadorResponse, TrabajadorResumen, CatalogoFicha, EstudioFicha } from '../interfaces/trabajadores.interface'
const rows=ref<TrabajadorResumen[]>([]),criterio=ref(''),page=ref(1),total=ref(0),lastPage=ref(1),loading=ref(false),loadingFicha=ref(false),error=ref(''),ficha=ref<FichaTrabajadorResponse|null>(null),tab=ref<'personal'|'laboral'|'academico'>('personal')
const academicCount=computed(()=>ficha.value?(ficha.value.profesiones.length+ficha.value.grados_instruccion.length+ficha.value.estudios.length+ficha.value.familiares.length):0)
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const r=await listarTrabajadores(criterio.value,page.value);rows.value=r.data;total.value=r.total;page.value=r.current_page;lastPage.value=r.last_page}catch(v){error.value=message(v)}finally{loading.value=false}}
async function openFicha(x:TrabajadorResumen){if(!x.registrado)return;loadingFicha.value=true;error.value='';tab.value='personal';try{ficha.value=await obtenerFichaTrabajador(x.id)}catch(v){error.value=message(v)}finally{loadingFicha.value=false}}
function move(value:number){if(value<1||value>lastPage.value)return;page.value=value;load()}
const text=(x:CatalogoFicha|null|undefined)=>x?.descripcion||x?.nombre||'—'
const grade=(x:{grado_instruccion?:CatalogoFicha|null;gradoInstruccion?:CatalogoFicha|null})=>text(x.grado_instruccion??x.gradoInstruccion)
const center=(x:EstudioFicha)=>text(x.centro_ensenanza??x.centroEnsenanza)
const formatDate=(v:string|null|undefined)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'—'
const formatMoney=(v:number|string|null)=>v===null?'—':Number(v).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})
function location(x:EstudioFicha){const d=x.distrito,p=d?.provincia,dep=p?.departamento,pais=dep?.pais;return [pais?.nombre,dep?.nombre,p?.nombre,d?.nombre].filter(Boolean).join(' / ')||'—'}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Trabajadores</nav><header class="hero"><div class="mark">TR</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Gestión de trabajadores</h1><p>Consulta de personas de planilla y su ficha laboral consolidada.</p></div><strong>{{total}} personas</strong></header><p v-if="error" class="flash">{{error}}</p><section class="filters"><form @submit.prevent="load(true)"><label>Buscar persona<input v-model.trim="criterio" placeholder="Nombre, apellidos, DNI o razón social"></label><button>Buscar</button><button v-if="criterio" type="button" class="soft" @click="criterio='';load(true)">Limpiar</button></form></section><section class="table-card"><header><small>PERSONAL DE PLANILLA</small><h2>Personas registradas</h2></header><div v-if="loading" class="empty">Consultando trabajadores…</div><div v-else-if="!rows.length" class="empty">No se encontraron personas con ese criterio.</div><div v-else class="scroll"><table><thead><tr><th>Nombre completo</th><th>DNI / RUC</th><th>Tipo</th><th>Contacto</th><th>Estado trabajador</th><th>Ficha</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.nombre_completo}}</b><small v-if="x.razon_social">{{x.razon_social}}</small></td><td>{{x.dni||'—'}}<small v-if="x.ruc">RUC: {{x.ruc}}</small></td><td><span class="type">{{x.tipo}}</span></td><td>{{x.email||'—'}}<small>{{x.celular||'Sin celular'}}</small></td><td><span :class="x.registrado?'active':'inactive'">{{x.registrado?'Registrado':'Sin registrar'}}</span></td><td><button class="detail" :disabled="!x.registrado||loadingFicha" :title="x.registrado?'Ver ficha completa':'Debe registrar datos laborales primero'" @click="openFicha(x)">Ver ficha</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="move(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="move(page+1)">Siguiente</button></footer></section><div v-if="ficha" class="backdrop" @mousedown.self="ficha=null"><article class="dialog"><header><div class="mark">FT</div><div><small>FICHA DEL TRABAJADOR</small><h2>{{ficha.persona.nombre_completo}}</h2><p>DNI: {{ficha.persona.dni||'—'}}</p></div><button class="close" @click="ficha=null">×</button></header><div class="tabs"><button :class="{selected:tab==='personal'}" @click="tab='personal'">Información personal</button><button :class="{selected:tab==='laboral'}" @click="tab='laboral'">Información laboral <b>{{ficha.datos_trabajador.length}}</b></button><button :class="{selected:tab==='academico'}" @click="tab='academico'">Datos académicos <b>{{academicCount}}</b></button></div><div class="content"><dl v-if="tab==='personal'" class="personal"><dt>Apellido paterno</dt><dd>{{ficha.persona.apellido_paterno||'—'}}</dd><dt>Apellido materno</dt><dd>{{ficha.persona.apellido_materno||'—'}}</dd><dt>Nombres</dt><dd>{{ficha.persona.nombre||'—'}}</dd><dt>DNI</dt><dd>{{ficha.persona.dni||'—'}}</dd><dt>Fecha de nacimiento</dt><dd>{{formatDate(ficha.persona.fecha_nacimiento)}}</dd><dt>Sexo</dt><dd>{{ficha.persona.sexo?.toLowerCase()==='m'?'Masculino':ficha.persona.sexo?.toLowerCase()==='f'?'Femenino':'—'}}</dd></dl><template v-else-if="tab==='laboral'"><div v-if="!ficha.datos_trabajador.length" class="empty compact">No existen datos laborales activos.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Régimen</th><th>AFP</th><th>Ingreso</th><th>Cese</th><th>Sueldo base</th><th>Estado</th></tr></thead><tbody><tr v-for="x in ficha.datos_trabajador" :key="x.id"><td>{{x.codigo_trabajador||'—'}}</td><td>{{text(x.regimen)}}</td><td>{{text(x.afp)}}</td><td>{{formatDate(x.fecha_ingreso)}}</td><td>{{formatDate(x.fecha_cese)}}</td><td>S/ {{formatMoney(x.sueldo_base)}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td></tr></tbody></table></div></template><div v-else class="academic"><h3>Profesiones <b>{{ficha.profesiones.length}}</b></h3><div v-if="!ficha.profesiones.length" class="empty compact">No hay profesiones registradas.</div><table v-else><thead><tr><th>Código</th><th>Profesión</th></tr></thead><tbody><tr v-for="x in ficha.profesiones" :key="x.id"><td>{{x.profesion?.codigo||'—'}}</td><td>{{text(x.profesion)}}</td></tr></tbody></table><h3>Grados de instrucción <b>{{ficha.grados_instruccion.length}}</b></h3><div v-if="!ficha.grados_instruccion.length" class="empty compact">No hay grados registrados.</div><table v-else><thead><tr><th>Código</th><th>Grado</th></tr></thead><tbody><tr v-for="x in ficha.grados_instruccion" :key="x.id"><td>{{(x.grado_instruccion??x.gradoInstruccion)?.codigo||'—'}}</td><td>{{grade(x)}}</td></tr></tbody></table><h3>Estudios <b>{{ficha.estudios.length}}</b></h3><div v-if="!ficha.estudios.length" class="empty compact">No hay estudios registrados.</div><div v-else class="scroll"><table><thead><tr><th>Grado</th><th>Centro</th><th>Ubicación</th><th>Periodo</th><th>Calificación</th><th>Nota</th></tr></thead><tbody><tr v-for="x in ficha.estudios" :key="x.id"><td>{{grade(x)}}</td><td>{{center(x)}}</td><td>{{location(x)}}</td><td>{{formatDate(x.fechadesde)}} al {{formatDate(x.fechahasta)}}</td><td>{{x.califica??'—'}}</td><td>{{x.nota??'—'}}</td></tr></tbody></table></div><h3>Familiares <b>{{ficha.familiares.length}}</b></h3><div v-if="!ficha.familiares.length" class="empty compact">No hay familiares activos registrados.</div><table v-else><thead><tr><th>Apellidos y nombres</th><th>Vínculo</th><th>Documento</th><th>Sexo</th><th>Nacimiento</th></tr></thead><tbody><tr v-for="x in ficha.familiares" :key="x.id"><td>{{[x.apellidopaterno,x.apellidomaterno,x.nombres].filter(Boolean).join(' ')}}</td><td>{{x.vinculo||'—'}}</td><td>{{x.tipoidentidad||'—'}} · {{x.numerodocumento||'—'}}</td><td>{{x.sexo||'—'}}</td><td>{{formatDate(x.fechanacimiento)}}</td></tr></tbody></table></div></div><footer><a :href="urlFichaTrabajadorPdf(ficha.persona.id)" target="_blank" rel="noopener">Exportar PDF</a><button class="soft" @click="ficha=null">Cerrar</button></footer></article></div></div></template>
<style scoped>
.page{--accent:#277f78;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;flex:0 0 auto;border-radius:10px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.dialog header p{margin:0;color:#7e8a90;font-size:.67rem}.hero>strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#e9f5f3;font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.filters{margin-top:10px;padding:12px;border-radius:9px;background:#fff}.filters form{display:flex;align-items:end;gap:6px}.filters label{width:min(520px,100%);margin-right:auto;font-size:.5rem}.filters input{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.54rem}.filters button,.table-card footer button,.dialog footer button,.dialog footer a{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem;text-decoration:none}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left;vertical-align:middle}th{color:#fff;background:#526d79}td>b,td>small{display:block}.type,.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.43rem;text-transform:capitalize}.type{color:#3a6378;background:#eaf4f8}.active{color:#287154;background:#e6f7ee}.inactive{color:#8a6570;background:#f1edef}.detail{padding:6px 9px;border:0;border-radius:5px;color:#17665f;background:#def3f0;font-size:.47rem}.detail:disabled{cursor:not-allowed;opacity:.45}.empty{padding:45px;text-align:center;font-size:.6rem}.compact{padding:20px;background:#f7f9fa}.table-card>footer{padding:10px;display:flex;align-items:center;justify-content:center;gap:10px}.table-card>footer span{font-size:.52rem}.table-card>footer button:disabled{opacity:.4}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3daa}.dialog{width:min(1100px,100%);max-height:92vh;display:flex;flex-direction:column;border-radius:12px;background:#fff;overflow:hidden}.dialog>header{padding:18px 20px;display:flex;align-items:center;gap:10px}.dialog h2{margin:2px 0;font-size:1rem}.close{margin-left:auto;border:0;color:#59666c;background:none;font-size:1.35rem}.tabs{padding:0 20px;display:flex;gap:5px;border-bottom:1px solid #dce3e5}.tabs button{padding:9px;border:0;border-bottom:3px solid transparent;color:#66767c;background:none;font-size:.52rem}.tabs button.selected{border-color:var(--accent);color:var(--accent);font-weight:700}.tabs b,.academic h3 b{padding:2px 5px;border-radius:8px;color:#fff;background:var(--accent);font-size:.42rem}.content{padding:16px 20px;overflow:auto}.personal{display:grid;grid-template-columns:190px 1fr;margin:0;border:1px solid #e1e6e8;font-size:.55rem}.personal dt,.personal dd{margin:0;padding:10px;border-bottom:1px solid #e1e6e8}.personal dt{background:#f4f7f8}.academic h3{margin:16px 0 6px;font-size:.64rem}.academic h3:first-child{margin-top:0}.academic table{border:1px solid #e2e7e9}.dialog>footer{padding:12px 20px;display:flex;justify-content:flex-end;gap:7px;border-top:1px solid #e3e8ea}@media(max-width:760px){.hero,.filters form{flex-wrap:wrap}.hero>strong{margin-left:0}.filters label{width:100%}.dialog{max-height:96vh}.tabs{overflow:auto}.tabs button{white-space:nowrap}.personal{grid-template-columns:1fr}.personal dd{padding-top:4px}.personal dt{padding-bottom:4px}.dialog>footer{flex-wrap:wrap}table{min-width:760px}}
</style>
